def solution() -> int:
    C = [
        [2, 2],
        [2, 1]
    ]
    n = len(C)
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, mask):
        if i == n:
            return 0
        best = 10**9
        for j in range(n):
            if (mask >> j) & 1:
                val = C[i][j] + dp(i+1, mask ^ (1 << j))
                if val < best:
                    best = val
        return best

    return int(dp(0, (1 << n) - 1))

