from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Graph representation: directed edges (u -> v, weight)
    adj = {
        0: [],
        1: [(3, 2)],
        2: [(0, 6), (1, 5), (3, 3)],
        3: [(0, 3)]
    }
    start, goal = 0, 3

    # Dijkstra's algorithm
    dist = {0: 0, 1: float('inf'), 2: float('inf'), 3: float('inf')}
    prev = {}

    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        if u == goal:
            break
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))

    if dist[goal] == float('inf'):
        return [], -1

    # Reconstruct path from start to goal
    path = []
    cur = goal
    while cur in prev:
        path.append(cur)
        cur = prev[cur]
    if dist.get(start, 0) == 0 and cur == start:
        path.append(start)
    path.reverse()
    return path, int(dist[goal])

