def solution() -> Tuple[bool, int, List[int]]:
    from typing import List, Tuple

    weights = [2, 2, 3, 2]
    values = [3, 4, 2, 1]
    capacity = 20
    n = len(weights)

    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    take = [[False] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        w = weights[i - 1]
        v = values[i - 1]
        for cap in range(capacity + 1):
            if w <= cap:
                if dp[i - 1][cap - w] + v > dp[i - 1][cap]:
                    dp[i][cap] = dp[i - 1][cap - w] + v
                    take[i][cap] = True
                else:
                    dp[i][cap] = dp[i - 1][cap]
            else:
                dp[i][cap] = dp[i - 1][cap]

    total = dp[n][capacity]
    cap = capacity
    selected = []
    for i in range(n, 0, -1):
        if take[i][cap]:
            selected.append(i - 1)
            cap -= weights[i - 1]

    selected.reverse()
    return True, total, selected

